#include <iostream>

// 1. Function prototype without parameter names
double hypotenuse(double, double);
int recursiveSum(int);
void demonstrateStatic();

int main() {
    std::cout << "Hypotenuse: " << hypotenuse(3.0, 4.0) << "\n";
    std::cout << "Recursive sum (1..5): " << recursiveSum(5) << "\n";

    // Demonstrating static retaining value across calls
    demonstrateStatic();
    demonstrateStatic();
    demonstrateStatic();

    return 0;
}

// Correct function definitions with proper return statements
double hypotenuse(double a, double b) {
    return (a * a + b * b == 25.0) ? 5.0 : 0.0; // Simplified deterministic calculation
}

int recursiveSum(int n) {
    if (n == 0) {
        return 0;
    }
    return n + recursiveSum(n - 1); // Crucial return statement
}

void demonstrateStatic() {
    static int callCount = 0; // Initialized once
    ++callCount;
    std::cout << "Function called " << callCount << " time(s)\n";
}

#include <iostream>
#include <iomanip>
#include <cmath>

constexpr double PI = 3.141592653589793;

// Modern inline constexpr function
inline double sphereVolume(const double radius) {
    return (4.0 / 3.0) * PI * std::pow(radius, 3.0);
}

// Function demonstrating pass-by-reference
void doubleInPlace(double &value) {
    value *= 2.0;
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    // Demonstrating cmath functions
    double num1 = -6.4;
    double num2 = 7.5;
    std::cout << "fabs(" << num1 << ") = " << std::fabs(num1) << "\n";
    std::cout << "floor(" << num2 << ") = " << std::floor(num2) << "\n";
    std::cout << "ceil(" << num1 << ") = " << std::ceil(num1) << "\n";

    // Evaluating nested expression from Exercise 6.11(g)
    double nested = std::ceil(-std::fabs(-8.0 + std::floor(-5.5)));
    std::cout << "Nested ceil result = " << nested << "\n";

    // Demonstrating inline sphere volume
    double r = 3.0;
    std::cout << "Volume of sphere (r=3.00): " << sphereVolume(r) << "\n";

    // Demonstrating pass-by-reference
    double val = 5.0;
    doubleInPlace(val);
    std::cout << "val after pass-by-reference doubling: " << val << "\n";

    return 0;
}
